package com.udcf.modules.matrix;

import com.udcf.modules.mpi.PayloadGenerator;

/**
 * The deterministic matrices of Experiment 10: square N x N, row-major {@code double[]} (element
 * (i, j) at {@code i * n + j}), generated by Experiment 9's {@link PayloadGenerator} from a seed.
 *
 * <p><b>Seeds.</b> A uses {@code seed ^ SALT_A}, B uses {@code seed ^ SALT_B}. XOR with a constant is a
 * bijection and the salts differ, so A's and B's seeds differ for every seed. Because A and B are
 * exactly {@code PayloadGenerator.vector(derivedSeed, n * n)}, an Experiment 9 collective given the
 * derived seed regenerates the same matrix (E10b reuses this for the broadcast of B).</p>
 *
 * <p><b>Range.</b> Every value is in [-1000, 1000), so finite. Every product of two values is below
 * 1e6 in size and every element of C below n * 1e6 (at most 46340 * 1e6, about 4.6e10, for any int n
 * whose square fits an int): no NaN and no infinity can occur.</p>
 */
public final class MatrixGenerator {

    /** XORed into the seed for A. */
    static final long SALT_A = 0xA5A5A5A5A5A5A5A5L;
    /** XORed into the seed for B; differs from {@link #SALT_A}. */
    static final long SALT_B = 0x5A5A5A5A5A5A5A5AL;

    private MatrixGenerator() {
    }

    /** The seed A is generated from. */
    public static long seedA(long seed) {
        return seed ^ SALT_A;
    }

    /** The seed B is generated from. */
    public static long seedB(long seed) {
        return seed ^ SALT_B;
    }

    /** A, n x n, row-major. */
    public static double[] a(long seed, int n) {
        return PayloadGenerator.vector(seedA(seed), elements(n));
    }

    /** B, n x n, row-major. */
    public static double[] b(long seed, int n) {
        return PayloadGenerator.vector(seedB(seed), elements(n));
    }

    /** n * n; refused when n &lt; 1 or the square does not fit an int. */
    static int elements(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("n must be >= 1, was " + n);
        }
        return Math.multiplyExact(n, n);
    }
}
